mapper.select:

WHERE t.user_id = #{userId}

    ORDER BY t.course_id IS NULL, t.course_id, t.created_at DESC
    ORDER BY t.site_id IS NULL, t.site_id, t.created_at DESC
    ORDER BY t.created_at DESC

LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE thinkbox
SET is_edited  = CASE WHEN body <> #{body} THEN 1 ELSE is_edited END,
    body       = #{body},
    is_private = #{isPrivate}
WHERE thinkbox_id = #{thinkboxId}

mapper.select:
WHERE t.user_id = #{userId} AND t.is_private = 0 AND EXISTS (SELECT 1 FROM user_agreement ua WHERE ua.user_id = t.user_id AND ua.agreement_type = 'EBOOK_PUBLIC' AND ua.withdrawn_at IS NULL)
AND t.course_id = #{courseId}
ORDER BY t.created_at
